-- MT2009_PLUS_ITEMSHOP_V3_V1: generated by tools/itemshop3/gen_itemshop3_sql.py - do not edit by hand.
-- The second ItemShop (app/shop3, "V3 Itemshop Premium"): its own tables, and views onto our catalogue
-- (itemshop.ishop_items / ishop_category / ishop_bundle_items) and world.item_proto. Run as root by
-- playerbot-migrate (apply.sh) after itemshop_schema.sql, at every start; idempotent.
CREATE DATABASE IF NOT EXISTS itemshop3 CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
GRANT ALL PRIVILEGES ON itemshop3.* TO 'metin2'@'%';
FLUSH PRIVILEGES;

-- The package's own tables (web_db/db.sql), utf8mb4, keys inline.
CREATE TABLE IF NOT EXISTS itemshop3.history (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, account INT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, item INT NOT NULL, taken INT(1) NOT NULL DEFAULT 1, pay_type INT(1) NOT NULL, coins INT NOT NULL, type INT(1) NOT NULL DEFAULT 1, from_account INT NOT NULL DEFAULT 0, to_player INT NOT NULL DEFAULT 0, KEY account (account), KEY item (item)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.settings (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(24) NOT NULL, value VARCHAR(64) NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY name (name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.locale_game (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, type VARCHAR(64) NOT NULL, bonus INT NOT NULL, lang ENUM('ar','cs','da','de','el','en','es','fr','hu','it','nl','pl','pt','ro','ru','tr') NOT NULL, name TEXT NOT NULL, UNIQUE KEY type_lang (type, lang), KEY bonus (bonus)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.skills (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, vnum INT NOT NULL, lang ENUM('ar','cs','da','de','el','en','es','fr','hu','it','nl','pl','pt','ro','ru','tr') NOT NULL, type VARCHAR(16) NOT NULL, name VARCHAR(64) NOT NULL, UNIQUE KEY vnum_lang (vnum, lang)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.mob_names (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, vnum INT NOT NULL, lang ENUM('ar','cs','da','de','el','en','es','fr','hu','it','nl','pl','pt','ro','ru','tr') NOT NULL, name VARCHAR(64) NOT NULL, KEY vnum (vnum)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.price_list (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, type INT NOT NULL DEFAULT 0, amount INT NOT NULL, value INT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.redeem_codes (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, code VARCHAR(16) NOT NULL, type INT(1) NOT NULL DEFAULT 1, item INT NOT NULL DEFAULT 0, UNIQUE KEY code (code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.slider (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, img TEXT NOT NULL, title TEXT NOT NULL, text TEXT NOT NULL, link TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.transactions (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, account INT NOT NULL, type INT NOT NULL DEFAULT 0, amount INT NOT NULL, value INT NOT NULL, code VARCHAR(64) NOT NULL, email VARCHAR(64) NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.transactions_admins (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, account INT NOT NULL, to_account INT NOT NULL, type INT NOT NULL, value INT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.wheel_players (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, account INT NOT NULL, level INT NOT NULL DEFAULT 1, stage INT NOT NULL DEFAULT 0, last_spin DATETIME DEFAULT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY account (account)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

