-- MT2009_PLUS_ITEMSHOP_V3_V3: the catalogue is the IN-GAME shop's (the owner, 24.10.2026: "the new shop must have
-- exactly the same things as the old in-game shop") - common.itemshop_items with its promotions and flash offers,
-- in the in-game window's categories (root/uiitemshop.py ITEMSHOP_CATEGORIES: index ranges, every line in Smocze
-- Znaki also under "Smocze Znaki", a running promotion under "Polecane", a flash offer only under "Oferty
-- Blyskawiczne"; a line outside all of them is not shown). The web catalogue (itemshop.ishop_items) gives only
-- the descriptions and pictures of the same vnums.
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.categories AS SELECT 1 AS id, 'Polecane' AS pl, 'Polecane' AS en, 'Polecane' AS ro, 'star' AS icon, 1 AS active, 'featured' AS kind, 0 AS sort, 0 AS parent UNION ALL SELECT 2 AS id, 'Wyposażenie' AS pl, 'Wyposażenie' AS en, 'Wyposażenie' AS ro, 'shield-alt' AS icon, 1 AS active, 'items' AS kind, 1 AS sort, 0 AS parent UNION ALL SELECT 3 AS id, 'Uszlachetnianie' AS pl, 'Uszlachetnianie' AS en, 'Uszlachetnianie' AS ro, 'refine' AS icon, 1 AS active, 'items' AS kind, 2 AS sort, 0 AS parent UNION ALL SELECT 4 AS id, 'VIPy' AS pl, 'VIPy' AS en, 'VIPy' AS ro, 'gem' AS icon, 1 AS active, 'items' AS kind, 3 AS sort, 0 AS parent UNION ALL SELECT 18 AS id, 'Wygląd postaci' AS pl, 'Wygląd postaci' AS en, 'Wygląd postaci' AS ro, 'look' AS icon, 1 AS active, 'group' AS kind, 4 AS sort, 0 AS parent UNION ALL SELECT 5 AS id, 'Fryzury' AS pl, 'Fryzury' AS en, 'Fryzury' AS ro, 'cut' AS icon, 1 AS active, 'items' AS kind, 5 AS sort, 18 AS parent UNION ALL SELECT 6 AS id, 'Kostiumy' AS pl, 'Kostiumy' AS en, 'Kostiumy' AS ro, 'tshirt' AS icon, 1 AS active, 'items' AS kind, 6 AS sort, 18 AS parent UNION ALL SELECT 7 AS id, 'Nakładki na broń i szarfy' AS pl, 'Nakładki na broń i szarfy' AS en, 'Nakładki na broń i szarfy' AS ro, 'khanda' AS icon, 1 AS active, 'items' AS kind, 7 AS sort, 18 AS parent UNION ALL SELECT 8 AS id, 'Pety' AS pl, 'Pety' AS en, 'Pety' AS ro, 'paw' AS icon, 1 AS active, 'items' AS kind, 8 AS sort, 18 AS parent UNION ALL SELECT 9 AS id, 'Mounty' AS pl, 'Mounty' AS en, 'Mounty' AS ro, 'horse' AS icon, 1 AS active, 'items' AS kind, 9 AS sort, 18 AS parent UNION ALL SELECT 19 AS id, 'Sety Bonusowe' AS pl, 'Sety Bonusowe' AS en, 'Sety Bonusowe' AS ro, 'gem' AS icon, 1 AS active, 'sets' AS kind, 10 AS sort, 18 AS parent UNION ALL SELECT 10 AS id, 'Małżeństwo' AS pl, 'Małżeństwo' AS en, 'Małżeństwo' AS ro, 'heart' AS icon, 1 AS active, 'items' AS kind, 11 AS sort, 0 AS parent UNION ALL SELECT 11 AS id, 'Zwoje i księgi' AS pl, 'Zwoje i księgi' AS en, 'Zwoje i księgi' AS ro, 'magic' AS icon, 1 AS active, 'items' AS kind, 12 AS sort, 0 AS parent UNION ALL SELECT 12 AS id, 'Smocze Znaki' AS pl, 'Smocze Znaki' AS en, 'Smocze Znaki' AS ro, 'marks' AS icon, 1 AS active, 'marks' AS kind, 13 AS sort, 0 AS parent UNION ALL SELECT 13 AS id, 'Kupony SM' AS pl, 'Kupony SM' AS en, 'Kupony SM' AS ro, 'service' AS icon, 1 AS active, 'items' AS kind, 14 AS sort, 0 AS parent UNION ALL SELECT 14 AS id, 'Wykorzystaj voucher' AS pl, 'Wykorzystaj voucher' AS en, 'Wykorzystaj voucher' AS ro, 'ticket' AS icon, 1 AS active, 'voucher' AS kind, 15 AS sort, 0 AS parent UNION ALL SELECT 15 AS id, 'Oferty Błyskawiczne' AS pl, 'Oferty Błyskawiczne' AS en, 'Oferty Błyskawiczne' AS ro, 'bolt' AS icon, 1 AS active, 'auctions' AS kind, 16 AS sort, 0 AS parent UNION ALL SELECT 16 AS id, 'Konto Premium' AS pl, 'Konto Premium' AS en, 'Konto Premium' AS ro, 'crown' AS icon, 1 AS active, 'premium' AS kind, 17 AS sort, 0 AS parent UNION ALL SELECT 17 AS id, 'Doładuj SM!' AS pl, 'Doładuj SM!' AS en, 'Doładuj SM!' AS ro, 'coins' AS icon, 1 AS active, 'topup' AS kind, 18 AS sort, 0 AS parent;
-- The flash offers' counters (the game's base dump has the table; a world without it gets an empty one).
CREATE TABLE IF NOT EXISTS player.itemshop_time_auction (item_index INT(10) NOT NULL, buy_count INT(10) NOT NULL DEFAULT 0, PRIMARY KEY (item_index)) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- MT2009_PLUS_ITEMSHOP_V3_V6: the V3-only lines (tools/itemshop3/gen_global_catalog.py -> global/v3_extra.json): what
-- the big servers' list has and the in-game shop does not, the set pieces not sold yet, the set chests. Only this
-- shop lists them (the in-game window reads common.itemshop_items). Ids from 100000, never reused (global/ids.json).
CREATE TABLE IF NOT EXISTS itemshop3.v3_lines (id INT NOT NULL PRIMARY KEY, vnum INT NOT NULL DEFAULT 0, count INT NOT NULL DEFAULT 1, price INT NOT NULL, pay_type TINYINT NOT NULL DEFAULT 1, category INT NOT NULL, minutes INT NOT NULL DEFAULT 0, suffix VARCHAR(32) NOT NULL DEFAULT '', name VARCHAR(96) NOT NULL DEFAULT '', image VARCHAR(96) NOT NULL DEFAULT '', description TEXT NULL, chest INT NOT NULL DEFAULT 0, set_id INT NOT NULL DEFAULT 0, min_level INT NOT NULL DEFAULT 0, source VARCHAR(255) NOT NULL DEFAULT '', KEY vnum (vnum)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.set_items (vnum INT NOT NULL, set_id INT NOT NULL, sort INT NOT NULL, PRIMARY KEY (vnum, set_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.chests (id INT NOT NULL PRIMARY KEY, line INT NOT NULL, set_id INT NOT NULL, name VARCHAR(96) NOT NULL, price INT NOT NULL, image VARCHAR(96) NOT NULL, UNIQUE KEY line (line)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- a chest's possible results: chance in parts per million (they sum to 1 000 000); a result gives every item_no once,
-- one of its alternatives (alt_no) - the one the buying character can wear (sex / class), at random among those
CREATE TABLE IF NOT EXISTS itemshop3.chest_drops (chest_id INT NOT NULL, drop_no INT NOT NULL, ppm INT NOT NULL, label VARCHAR(160) NOT NULL, kind VARCHAR(16) NOT NULL, PRIMARY KEY (chest_id, drop_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS itemshop3.chest_items (chest_id INT NOT NULL, drop_no INT NOT NULL, item_no INT NOT NULL, alt_no INT NOT NULL, vnum INT NOT NULL, count INT NOT NULL DEFAULT 1, minutes INT NOT NULL DEFAULT 0, PRIMARY KEY (chest_id, drop_no, item_no, alt_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- every roll of a chest bought (audit): the purchase token, the roll of the quantity, the result and its chance, the
-- random number drawn (1..1 000 000), the items and their player.item_award ids
CREATE TABLE IF NOT EXISTS itemshop3.chest_rolls (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, token CHAR(32) NOT NULL, account INT NOT NULL, pid INT NOT NULL DEFAULT 0, line INT NOT NULL, chest_id INT NOT NULL, roll_no INT NOT NULL, drop_no INT NOT NULL, ppm INT NOT NULL, rnd INT NOT NULL, label VARCHAR(160) NOT NULL, vnums VARCHAR(255) NOT NULL, award_ids VARCHAR(255) NOT NULL, price INT NOT NULL, pay_type TINYINT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY account (account), KEY token (token), KEY chest (chest_id, date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- one row a purchase (the token the item window hands out): a second request with the same token (a double click,
-- a reload) is not paid again - it shows the first one's result
CREATE TABLE IF NOT EXISTS itemshop3.purchase_tokens (token CHAR(32) NOT NULL PRIMARY KEY, account INT NOT NULL, line INT NOT NULL, qty INT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, result MEDIUMTEXT NULL, KEY account (account)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
START TRANSACTION;
DELETE FROM itemshop3.v3_lines;
DELETE FROM itemshop3.set_items;
DELETE FROM itemshop3.chests;
DELETE FROM itemshop3.chest_drops;
DELETE FROM itemshop3.chest_items;
