-- a chest's items with what the shop needs to pick the one that fits the character (the wear filter's antiflags)
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.chest_items_view AS SELECT c.chest_id, c.drop_no, c.item_no, c.alt_no, c.vnum, c.count, c.minutes, IF(COALESCE(p.antiflag, 0) & 1, 1, 0) AS anti_female, IF(COALESCE(p.antiflag, 0) & 2, 1, 0) AS anti_male, IF(COALESCE(p.antiflag, 0) & 4, 1, 0) AS anti_warrior, IF(COALESCE(p.antiflag, 0) & 8, 1, 0) AS anti_assassin, IF(COALESCE(p.antiflag, 0) & 16, 1, 0) AS anti_sura, IF(COALESCE(p.antiflag, 0) & 32, 1, 0) AS anti_shaman, IF(COALESCE(p.antiflag, 0) & 262144, 1, 0) AS anti_wolfman, COALESCE(CONVERT(p.locale_name USING utf8mb4), CONCAT('Vnum: ', c.vnum)) AS name FROM itemshop3.chest_items c LEFT JOIN world.item_proto p ON p.vnum = c.vnum;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.shop AS SELECT i.`index` AS id, CASE WHEN (ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0) THEN 15 ELSE COALESCE(NULLIF(CASE WHEN i.`index` BETWEEN 1 AND 99 THEN 2 WHEN i.`index` BETWEEN 451 AND 459 THEN 3 WHEN i.`index` BETWEEN 101 AND 113 THEN 4 WHEN i.`index` BETWEEN 301 AND 450 THEN 5 WHEN i.`index` BETWEEN 10000 AND 19999 THEN 5 WHEN i.`index` BETWEEN 20000 AND 29999 THEN 6 WHEN i.`index` BETWEEN 30000 AND 39999 THEN 7 WHEN i.`index` BETWEEN 40000 AND 49999 THEN 8 WHEN i.`index` BETWEEN 50000 AND 59999 THEN 9 WHEN i.`index` BETWEEN 201 AND 299 THEN 10 WHEN i.`index` BETWEEN 601 AND 699 THEN 11 WHEN i.`index` BETWEEN 901 AND 905 THEN 13 ELSE 0 END, 0), IF(i.currency + 0 = 2, 12, 0)) END AS category, '2026-01-01 00:00:00' AS date, 1 AS type, (SELECT d.`desc` FROM itemshop.ishop_items d WHERE d.vnum = i.vnum AND d.`desc` IS NOT NULL AND d.`desc` <> '' ORDER BY d.id LIMIT 1) AS description, i.currency + 0 AS pay_type, IF((pm.item_index IS NOT NULL AND NOW() >= pm.start_time AND NOW() < pm.end_time), pm.price, i.price) AS coins, i.price AS base_price, IF((pm.item_index IS NOT NULL AND NOW() >= pm.start_time AND NOW() < pm.end_time), 1, 0) AS promo, IF((pm.item_index IS NOT NULL AND NOW() >= pm.start_time AND NOW() < pm.end_time), pm.end_time, NULL) AS promo_end, i.count AS count, i.vnum AS vnum, 0 AS socket0, 0 AS socket1, 0 AS socket2, 0 AS socket3, 0 AS socket4, 0 AS socket5, 0 AS attrtype0, 0 AS attrvalue0, 0 AS attrtype1, 0 AS attrvalue1, 0 AS attrtype2, 0 AS attrvalue2, 0 AS attrtype3, 0 AS attrvalue3, 0 AS attrtype4, 0 AS attrvalue4, 0 AS attrtype5, 0 AS attrvalue5, 0 AS attrtype6, 0 AS attrvalue6, IF((i.vnum IN (40600,40601,40602,40603,40604,40605,40700,40701,40702,40703,40704,40705,40710,40711,40712,40713,40714,40715,40800,40801,40802,40803,40804,40805,40810,40811,40812,40813,40814,40815,40820,40821,40822,40823,40824,40825,40830,40831,40832,40833,40834,40835,40840,40841,40842,40843,40844,40845,40850,40851,40852,40853,40854,40855,40860,40861,40862,40863,40864,40865,40870,40871,40872,40873,40874,40875,40880,40881,40882,40883,40884,40885,40900,40901,40902,40903,40904,40905,40910,40911,40912,40913,40914,40915,40920,40921,40922,40923,40924,40925,40940,40941,40942,40943,40944,40945,40950,40951,40952,40953,40954,40955,40960,40961,40962,40963,40964,40965,40970,40971,40972,40973,40974,40975,40980,40981,40982,40983,40984,40985,40990,40991,40992,40993,40994,40995,42900,42901,42904,42905,42908,42909,42924,42925,42926,42927,42928,42929,42930,42931,42932,42933,42934,42935,42936,42937,42938,42939,42940,42941,42942,42943,42944,42945,42946,42947,42948,42949,42950,42951,42952,42953,42954,42955,42958,42959,42960,42961,42962,42963,45900,45901,45904,45905,45908,45909,45924,45925,45926,45927,45928,45929,45930,45931,45932,45933,45934,45935,45936,45937,45938,45939,45940,45941,45942,45943,45944,45945,45946,45947,45948,45949,45950,45951,45952,45953,45954,45955,45958,45959,45960,45961,45962,45963,85200,85201,85202,85203,85204,85205,85206,85207,85208,85209,85210,85211,85212,85214,85215,85216,85217) AND COALESCE((SELECT qf.lValue FROM player.quest qf WHERE qf.dwPID = 0 AND qf.szName = 'mt2009_arezzo_closed' LIMIT 1), 1) > 0), 0, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), IF(NOW() >= ta.start_time AND NOW() < ta.end_time AND (ta.max_amount = 0 OR COALESCE(tc.buy_count, 0) < ta.max_amount), 1, 0), 1)) AS available, NULL AS last_bought, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), ta.end_time, NULL) AS expire, 0 AS discount, NULL AS discount_expire, 0 AS polymorph, 'FIX' AS book_type, 0 AS book, 0 AS time, 0 AS limit_all, 0 AS limit_account, NULL AS bonuses, 0 AS bonuses_count, 0 AS friend, 0 AS wheel_level, 0 AS jackpot, IF(COALESCE(pr.antiflag, 0) & 1, 1, 0) AS anti_female, IF(COALESCE(pr.antiflag, 0) & 2, 1, 0) AS anti_male, IF(COALESCE(pr.antiflag, 0) & 4, 1, 0) AS anti_warrior, IF(COALESCE(pr.antiflag, 0) & 8, 1, 0) AS anti_assassin, IF(COALESCE(pr.antiflag, 0) & 16, 1, 0) AS anti_sura, IF(COALESCE(pr.antiflag, 0) & 32, 1, 0) AS anti_shaman, IF(COALESCE(pr.antiflag, 0) & 262144, 1, 0) AS anti_wolfman, IF(COALESCE(pr.flag, 0) & 4 AND NOT COALESCE(pr.antiflag, 0) & 32768, 1, 0) AS stackable, GREATEST(COALESCE(pr.stack, 1), 1) AS max_stack, CONCAT(COALESCE(CONVERT(pr.locale_name USING utf8mb4), CONCAT('Vnum: ', i.vnum)), CASE i.`index` WHEN 1 THEN ' (30 godzin)' WHEN 5 THEN ' (7 dni)' WHEN 101 THEN ' (1 dzień)' WHEN 102 THEN ' (3 dni)' WHEN 103 THEN ' (1 dzień)' WHEN 104 THEN ' (3 dni)' WHEN 105 THEN ' (1 dzień)' WHEN 106 THEN ' (3 dni)' WHEN 107 THEN ' (1 dzień)' WHEN 108 THEN ' (3 dni)' WHEN 109 THEN ' (1 dzień)' WHEN 110 THEN ' (3 dni)' WHEN 111 THEN ' (30 dni)' WHEN 112 THEN ' (30 dni)' WHEN 608 THEN ' (3+1)' WHEN 610 THEN ' (Paczka 25)' ELSE '' END) AS name, i.minLevel AS min_level, IF(pr.type = 3 AND pr.subtype = 31 AND i.vnum <> 72199, 1, 0) AS vip, COALESCE(pr.value0, 0) AS vip_type, COALESCE(pr.value1, 0) AS vip_hours, COALESCE(pr.value0, 0) AS value0, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), 1, 0) AS auction, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), ta.start_time, NULL) AS auction_start, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), ta.max_amount, 0) AS auction_max, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), ta.account_limit, 0) AS auction_account_limit, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0), COALESCE(tc.buy_count, 0), 0) AS auction_bought, IF((ta.item_index IS NOT NULL AND UNIX_TIMESTAMP(ta.start_time) > 0 AND UNIX_TIMESTAMP(ta.end_time) > 0) AND NOW() > ta.start_time - INTERVAL 1 DAY AND NOW() < ta.end_time + INTERVAL 1 HOUR, 1, 0) AS auction_visible, IF((i.vnum IN (40600,40601,40602,40603,40604,40605,40700,40701,40702,40703,40704,40705,40710,40711,40712,40713,40714,40715,40800,40801,40802,40803,40804,40805,40810,40811,40812,40813,40814,40815,40820,40821,40822,40823,40824,40825,40830,40831,40832,40833,40834,40835,40840,40841,40842,40843,40844,40845,40850,40851,40852,40853,40854,40855,40860,40861,40862,40863,40864,40865,40870,40871,40872,40873,40874,40875,40880,40881,40882,40883,40884,40885,40900,40901,40902,40903,40904,40905,40910,40911,40912,40913,40914,40915,40920,40921,40922,40923,40924,40925,40940,40941,40942,40943,40944,40945,40950,40951,40952,40953,40954,40955,40960,40961,40962,40963,40964,40965,40970,40971,40972,40973,40974,40975,40980,40981,40982,40983,40984,40985,40990,40991,40992,40993,40994,40995,42900,42901,42904,42905,42908,42909,42924,42925,42926,42927,42928,42929,42930,42931,42932,42933,42934,42935,42936,42937,42938,42939,42940,42941,42942,42943,42944,42945,42946,42947,42948,42949,42950,42951,42952,42953,42954,42955,42958,42959,42960,42961,42962,42963,45900,45901,45904,45905,45908,45909,45924,45925,45926,45927,45928,45929,45930,45931,45932,45933,45934,45935,45936,45937,45938,45939,45940,45941,45942,45943,45944,45945,45946,45947,45948,45949,45950,45951,45952,45953,45954,45955,45958,45959,45960,45961,45962,45963,85200,85201,85202,85203,85204,85205,85206,85207,85208,85209,85210,85211,85212,85214,85215,85216,85217) AND COALESCE((SELECT qf.lValue FROM player.quest qf WHERE qf.dwPID = 0 AND qf.szName = 'mt2009_arezzo_closed' LIMIT 1), 1) > 0), 1, 0) AS arezzo_locked, 'game' AS source, 0 AS chest, '' AS image, IF(EXISTS(SELECT 1 FROM itemshop3.set_items si WHERE si.vnum = i.vnum), 1, 0) AS in_sets, COALESCE((SELECT MIN(si.sort) FROM itemshop3.set_items si WHERE si.vnum = i.vnum), 0) AS set_sort, COALESCE((SELECT MIN(si.set_id) FROM itemshop3.set_items si WHERE si.vnum = i.vnum), 0) AS set_id FROM common.itemshop_items i LEFT JOIN common.itemshop_promotions pm ON pm.item_index = i.`index` LEFT JOIN common.itemshop_time_auctions ta ON ta.item_index = i.`index` LEFT JOIN player.itemshop_time_auction tc ON tc.item_index = i.`index` LEFT JOIN world.item_proto pr ON pr.vnum = i.vnum UNION ALL SELECT e.id AS id, e.category AS category, '2026-10-24 00:00:00' AS date, 1 AS type, COALESCE(NULLIF(e.description, ''), (SELECT d.`desc` FROM itemshop.ishop_items d WHERE d.vnum = e.vnum AND d.`desc` IS NOT NULL AND d.`desc` <> '' ORDER BY d.id LIMIT 1)) AS description, e.pay_type AS pay_type, e.price AS coins, e.price AS base_price, 0 AS promo, NULL AS promo_end, e.count AS count, e.vnum AS vnum, 0 AS socket0, 0 AS socket1, 0 AS socket2, 0 AS socket3, 0 AS socket4, 0 AS socket5, 0 AS attrtype0, 0 AS attrvalue0, 0 AS attrtype1, 0 AS attrvalue1, 0 AS attrtype2, 0 AS attrvalue2, 0 AS attrtype3, 0 AS attrvalue3, 0 AS attrtype4, 0 AS attrvalue4, 0 AS attrtype5, 0 AS attrvalue5, 0 AS attrtype6, 0 AS attrvalue6, 1 AS available, NULL AS last_bought, NULL AS expire, 0 AS discount, NULL AS discount_expire, 0 AS polymorph, 'FIX' AS book_type, 0 AS book, e.minutes AS time, 0 AS limit_all, 0 AS limit_account, NULL AS bonuses, 0 AS bonuses_count, 0 AS friend, 0 AS wheel_level, 0 AS jackpot, IF(COALESCE(pr.antiflag, 0) & 1, 1, 0) AS anti_female, IF(COALESCE(pr.antiflag, 0) & 2, 1, 0) AS anti_male, IF(COALESCE(pr.antiflag, 0) & 4, 1, 0) AS anti_warrior, IF(COALESCE(pr.antiflag, 0) & 8, 1, 0) AS anti_assassin, IF(COALESCE(pr.antiflag, 0) & 16, 1, 0) AS anti_sura, IF(COALESCE(pr.antiflag, 0) & 32, 1, 0) AS anti_shaman, IF(COALESCE(pr.antiflag, 0) & 262144, 1, 0) AS anti_wolfman, IF(e.chest > 0, 1, IF(COALESCE(pr.flag, 0) & 4 AND NOT COALESCE(pr.antiflag, 0) & 32768, 1, 0)) AS stackable, IF(e.chest > 0, 10, GREATEST(COALESCE(pr.stack, 1), 1)) AS max_stack, IF(e.chest > 0, e.name, CONCAT(COALESCE(CONVERT(pr.locale_name USING utf8mb4), CONCAT('Vnum: ', e.vnum)), IF(e.suffix <> '', CONCAT(' ', e.suffix), ''))) AS name, e.min_level AS min_level, IF(pr.type = 3 AND pr.subtype = 31 AND e.vnum <> 72199, 1, 0) AS vip, COALESCE(pr.value0, 0) AS vip_type, IF(e.minutes > 0, e.minutes DIV 60, COALESCE(pr.value1, 0)) AS vip_hours, COALESCE(pr.value0, 0) AS value0, 0 AS auction, NULL AS auction_start, 0 AS auction_max, 0 AS auction_account_limit, 0 AS auction_bought, 0 AS auction_visible, 0 AS arezzo_locked, 'v3' AS source, e.chest AS chest, e.image AS image, IF(e.chest > 0 OR EXISTS(SELECT 1 FROM itemshop3.set_items si WHERE si.vnum = e.vnum), 1, 0) AS in_sets, IF(e.chest > 0, e.set_id * 1000, COALESCE((SELECT MIN(si.sort) FROM itemshop3.set_items si WHERE si.vnum = e.vnum), 0)) AS set_sort, IF(e.chest > 0, e.set_id, COALESCE((SELECT MIN(si.set_id) FROM itemshop3.set_items si WHERE si.vnum = e.vnum), 0)) AS set_id FROM itemshop3.v3_lines e LEFT JOIN world.item_proto pr ON pr.vnum = e.vnum;
-- No package offers in the in-game catalogue (the view keeps its columns for the shop's code).
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.bundle_items AS SELECT b.id AS id, b.item_id AS item_id, b.vnum AS vnum, b.count AS count, b.socket0 AS socket0, b.socket1 AS socket1, b.socket2 AS socket2 FROM itemshop.ishop_bundle_items b WHERE 1 = 0;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.item_names AS SELECT p.vnum AS id, p.vnum AS vnum, 'pl' AS lang, p.locale_name AS name FROM world.item_proto p;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.itemdesc AS SELECT i.id AS id, i.vnum AS vnum, 'pl' AS lang, i.`desc` AS description FROM itemshop.ishop_items i WHERE i.`desc` IS NOT NULL AND i.`desc` <> '';
-- The picture of a vnum: img/item/<vnum>.png (tools/itemshop3/gen_shop_icons.py makes the missing ones from the
-- client's icons); the web catalogue's own icon name where it has one for the vnum.
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.item_list AS SELECT g.vnum AS id, g.vnum AS vnum, CONCAT('item/', COALESCE((SELECT MIN(i.vnum_icon) FROM itemshop.ishop_items i WHERE i.vnum = g.vnum), g.vnum), '.png') AS src FROM (SELECT vnum FROM common.itemshop_items UNION SELECT vnum FROM itemshop3.v3_lines WHERE vnum > 0 UNION SELECT vnum FROM itemshop3.chest_items) g;
-- What the shop wrote: the quantity of a purchase (the flash offers' account limit counts pieces).
ALTER TABLE itemshop3.history ADD COLUMN IF NOT EXISTS quantity INT NOT NULL DEFAULT 1;
-- The voucher tab's tries (5 a minute an account, as the game counts them per character).
CREATE TABLE IF NOT EXISTS itemshop3.voucher_tries (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, account INT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY account_date (account, date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE OR REPLACE SQL SECURITY DEFINER VIEW itemshop3.item_proto AS SELECT p.vnum AS id, COALESCE(ELT(p.type + 1, 'ITEM_NONE', 'ITEM_WEAPON', 'ITEM_ARMOR', 'ITEM_USE', 'ITEM_AUTOUSE', 'ITEM_MATERIAL', 'ITEM_SPECIAL', 'ITEM_TOOL', 'ITEM_LOTTERY', 'ITEM_ELK', 'ITEM_METIN', 'ITEM_CONTAINER', 'ITEM_FISH', 'ITEM_ROD', 'ITEM_RESOURCE', 'ITEM_CAMPFIRE', 'ITEM_UNIQUE', 'ITEM_SKILLBOOK', 'ITEM_QUEST', 'ITEM_POLYMORPH', 'ITEM_TREASURE_BOX', 'ITEM_TREASURE_KEY', 'ITEM_SKILLFORGET', 'ITEM_GIFTBOX', 'ITEM_PICK', 'ITEM_HAIR', 'ITEM_TOTEM', 'ITEM_BLEND', 'ITEM_COSTUME', 'ITEM_DS', 'ITEM_SPECIAL_DS', 'ITEM_EXTRACT', 'ITEM_SECONDARY_COIN', 'ITEM_RING', 'ITEM_BELT', 'ITEM_PET', 'ITEM_MEDIUM', 'ITEM_GACHA'), 'ITEM_NONE') AS item_type, CASE p.type WHEN 1 THEN COALESCE(ELT(p.subtype + 1, 'WEAPON_SWORD', 'WEAPON_DAGGER', 'WEAPON_BOW', 'WEAPON_TWO_HANDED', 'WEAPON_BELL', 'WEAPON_FAN', 'WEAPON_ARROW', 'WEAPON_MOUNT_SPEAR', 'WEAPON_CLAW', 'WEAPON_QUIVER', 'WEAPON_BOUQUET'), '') WHEN 2 THEN COALESCE(ELT(p.subtype + 1, 'ARMOR_BODY', 'ARMOR_HEAD', 'ARMOR_SHIELD', 'ARMOR_WRIST', 'ARMOR_FOOTS', 'ARMOR_NECK', 'ARMOR_EAR'), '') WHEN 3 THEN COALESCE(ELT(p.subtype + 1, 'USE_POTION', 'USE_TALISMAN', 'USE_TUNING', 'USE_MOVE', 'USE_TREASURE_BOX', 'USE_MONEYBAG', 'USE_BAIT', 'USE_ABILITY_UP', 'USE_AFFECT', 'USE_CREATE_STONE', 'USE_SPECIAL', 'USE_POTION_NODELAY', 'USE_CLEAR', 'USE_INVISIBILITY', 'USE_DETACHMENT', 'USE_BUCKET', 'USE_POTION_CONTINUE', 'USE_CLEAN_SOCKET', 'USE_CHANGE_ATTRIBUTE', 'USE_ADD_ATTRIBUTE', 'USE_ADD_ACCESSORY_SOCKET', 'USE_PUT_INTO_ACCESSORY_SOCKET', 'USE_ADD_ATTRIBUTE2', 'USE_RECIPE', 'USE_CHANGE_ATTRIBUTE2', 'USE_BIND', 'USE_UNBIND', 'USE_TIME_CHARGE_PER', 'USE_TIME_CHARGE_FIX', 'USE_PUT_INTO_BELT_SOCKET', 'USE_PUT_INTO_RING_SOCKET'), '') WHEN 10 THEN COALESCE(ELT(p.subtype + 1, 'METIN_NORMAL', 'METIN_GOLD'), '') WHEN 28 THEN COALESCE(ELT(p.subtype + 1, 'COSTUME_BODY', 'COSTUME_HAIR', 'COSTUME_MOUNT', 'COSTUME_ACCE', 'COSTUME_WEAPON'), '') ELSE '' END AS sub_type, p.size AS size, '' AS flag, p.magic_pct AS magic_pct, COALESCE(ELT(p.limittype0 + 1, 'LIMIT_NONE', 'LEVEL', 'STR', 'DEX', 'INT', 'CON', 'PC_BANG', 'REAL_TIME', 'REAL_TIME_FIRST_USE', 'TIMER_BASED_ON_WEAR'), 'LIMIT_NONE') AS limit_type0, p.limitvalue0 AS limit_value0, COALESCE(ELT(p.limittype1 + 1, 'LIMIT_NONE', 'LEVEL', 'STR', 'DEX', 'INT', 'CON', 'PC_BANG', 'REAL_TIME', 'REAL_TIME_FIRST_USE', 'TIMER_BASED_ON_WEAR'), 'LIMIT_NONE') AS limit_type1, p.limitvalue1 AS limit_value1, COALESCE(ELT(p.applytype0 + 1, 'APPLY_NONE', 'APPLY_MAX_HP', 'APPLY_MAX_SP', 'APPLY_CON', 'APPLY_INT', 'APPLY_STR', 'APPLY_DEX', 'APPLY_ATT_SPEED', 'APPLY_MOV_SPEED', 'APPLY_CAST_SPEED', 'APPLY_HP_REGEN', 'APPLY_SP_REGEN', 'APPLY_POISON_PCT', 'APPLY_STUN_PCT', 'APPLY_SLOW_PCT', 'APPLY_CRITICAL_PCT', 'APPLY_PENETRATE_PCT', 'APPLY_ATTBONUS_HUMAN', 'APPLY_ATTBONUS_ANIMAL', 'APPLY_ATTBONUS_ORC', 'APPLY_ATTBONUS_MILGYO', 'APPLY_ATTBONUS_UNDEAD', 'APPLY_ATTBONUS_DEVIL', 'APPLY_STEAL_HP', 'APPLY_STEAL_SP', 'APPLY_MANA_BURN_PCT', 'APPLY_DAMAGE_SP_RECOVER', 'APPLY_BLOCK', 'APPLY_DODGE', 'APPLY_RESIST_SWORD', 'APPLY_RESIST_TWOHAND', 'APPLY_RESIST_DAGGER', 'APPLY_RESIST_BELL', 'APPLY_RESIST_FAN', 'APPLY_RESIST_BOW', 'APPLY_RESIST_FIRE', 'APPLY_RESIST_ELEC', 'APPLY_RESIST_MAGIC', 'APPLY_RESIST_WIND', 'APPLY_REFLECT_MELEE', 'APPLY_REFLECT_CURSE', 'APPLY_POISON_REDUCE', 'APPLY_KILL_SP_RECOVER', 'APPLY_EXP_DOUBLE_BONUS', 'APPLY_GOLD_DOUBLE_BONUS', 'APPLY_ITEM_DROP_BONUS', 'APPLY_POTION_BONUS', 'APPLY_KILL_HP_RECOVER', 'APPLY_IMMUNE_STUN', 'APPLY_IMMUNE_SLOW', 'APPLY_IMMUNE_FALL', 'APPLY_SKILL', 'APPLY_BOW_DISTANCE', 'APPLY_ATT_GRADE_BONUS', 'APPLY_DEF_GRADE_BONUS', 'APPLY_MAGIC_ATT_GRADE', 'APPLY_MAGIC_DEF_GRADE', 'APPLY_CURSE_PCT', 'APPLY_MAX_STAMINA', 'APPLY_ATTBONUS_WARRIOR', 'APPLY_ATTBONUS_ASSASSIN', 'APPLY_ATTBONUS_SURA', 'APPLY_ATTBONUS_SHAMAN', 'APPLY_ATTBONUS_MONSTER', 'APPLY_MALL_ATTBONUS', 'APPLY_MALL_DEFBONUS', 'APPLY_MALL_EXPBONUS', 'APPLY_MALL_ITEMBONUS', 'APPLY_MALL_GOLDBONUS', 'APPLY_MAX_HP_PCT', 'APPLY_MAX